begin;
alter table clubs add column if not exists heritage_summary text;
alter table clubs add column if not exists history_source_url text;
alter table club_history add column if not exists event_year integer check(event_year between 1800 and 2200);
update club_history set event_year=extract(year from event_date)::int where event_year is null and event_date is not null;
update clubs set heritage_summary='מועדון תל אביבי בעל היסטוריה ארוכה של אליפויות וגביעים. בין ציוני הדרך האחרונים: אליפויות 2023/24 ו־2024/25 וגביע המדינה 2025/26, כפי שמופיע ברשימת התארים של ההתאחדות.',history_source_url='https://www.football.org.il/clubs/team-titles/?team_id=1061' where slug='maccabi-tel-aviv' and heritage_summary is null;
update clubs set heritage_summary='מכבי חיפה נוסדה ב־1913 וזכתה באליפות הראשונה ב־1984. ברשימת ההתאחדות מתועדות שלוש אליפויות רצופות בעונות 2020/21–2022/23.',history_source_url='https://www.mhaifafc.com/news/26467' where slug='maccabi-haifa' and heritage_summary is null;
update clubs set heritage_summary='הפועל תל אביב מציינת את 1923 כשנת ההיווסדות. בתולדותיה ניצחונות בגביע המדינה, דאבלים, זכייה באליפות אסיה לקבוצות ב־1967 והעפלה לשלב הבתים בליגת האלופות ב־2010.',history_source_url='https://www.htafc.co.il/היסטוריה-והישגים/' where slug='hapoel-tel-aviv' and heritage_summary is null;
update clubs set heritage_summary='מועדון באר שבע נוסד ב־1949. בין ציוני הדרך: האליפויות בשנות השבעים, שלוש האליפויות הרצופות ב־2016–2018 והאליפות השישית בעונת 2025/26.',history_source_url='https://hbsfc.co.il/club-history/' where slug='hapoel-beer-sheva' and heritage_summary is null;
update clubs set heritage_summary='בית״ר ירושלים נוסדה ב־1936. הגביע הראשון הגיע ב־1976, האליפות הראשונה ב־1986/87 וב־1991 עברה הקבוצה מאצטדיון ימק״א לטדי.',history_source_url='https://www.beitarfc.co.il/מועדון/' where slug='beitar-jerusalem' and heritage_summary is null;
update clubs set heritage_summary='שורשי הפועל חיפה באפריל 1924. המועדון היה הראשון ששיחק בשם הפועל, ובהמשך דרכו השתתף במוקדמות ליגת האלופות בעונת 1999/2000.',history_source_url='https://hapoel.org.il/היסטוריה/' where slug='hapoel-haifa' and heritage_summary is null;
update clubs set heritage_summary='המועדון של האוהדים משמר את מורשת הפועל ירושלים ההיסטורית, שנוסדה ב־1926. אוהדיו הקימו את קטמון ב־2007, רכשו את זכויות השם הפועל ירושלים ב־2020 וחזרו לליגת העל ב־2021. תוארי הקבוצה המקורית מוצגים כמורשת, תוך הבחנה מהישות הנוכחית.',history_source_url='https://www.hjfc.co.il/club-history' where slug='hapoel-jerusalem' and heritage_summary is null;
update clubs set heritage_summary='מכבי נתניה מזוהה עם תקופת הזוהר של שנות השבעים והשמונים. מסמך עיריית נתניה מונה חמש אליפויות בין 1970/71 ל־1982/83; רישום ההתאחדות מתעד גם זכייה בגביע הטוטו בליגת העל בעונת 2022/23.',history_source_url='https://www.netanya.muni.il/DocLib1/CityCouncil02092015.pdf' where slug='maccabi-netanya' and heritage_summary is null;
update clubs set heritage_summary='מכבי פתח תקווה היא מועדון ותיק בעיר. בין ציוני הדרך העדכניים הרשומים בהתאחדות: גביע הטוטו ב־2015/16 וגביע המדינה ב־2023/24.',history_source_url='https://www.football.org.il/team-details/?team_id=1064' where slug='maccabi-petah-tikva' and heritage_summary is null;
update clubs set heritage_summary='בני סכנין רשמה הישג היסטורי ב־2004 עם זכייה בגביע המדינה. UEFA תיעדה את הניצחון 4:1 על הפועל חיפה בגמר ואת ההעפלה למפעל אירופי בעקבותיו.',history_source_url='https://www.uefa.com/news-media/news/019d-0f8457421429-f3823795bc28-1000--sakhnin-claim-landmark-triumph/' where slug='bnei-sakhnin' and heritage_summary is null;
update clubs set heritage_summary='הפועל פתח תקווה זכתה באליפות הראשונה ב־1955 ובגביע המדינה השני בעונת 1991/92. האתר הרשמי מונה שש אליפויות ושני גביעי מדינה. שנות הזכיות ברצף האליפויות דורשות הצלבה נוספת בשל חוסר התאמה בטקסט ההיסטורי באתר.',history_source_url='https://www.hapoelpt.com/history' where slug='hapoel-petah-tikva' and heritage_summary is null;
update clubs set heritage_summary='קריית שמונה זכתה באליפות ליגת העל בעונת 2011/12 ובגביע המדינה ב־2013/14. ברישום ההתאחדות מופיעים גם גביעי טוטו ואלוף האלופים בעונת 2015/16.',history_source_url='https://www.football.org.il/clubs/team-titles/?team_id=2182' where slug='ironi-kiryat-shmona' and heritage_summary is null;
update clubs set heritage_summary='הפועל רמת גן זכתה בגביע המדינה ב־2003 כשהייתה בליגת המשנה. ב־2013 זכתה שוב, עם ניצחון בפנדלים על קריית שמונה, כפי שתועד ב־UEFA.',history_source_url='https://de.uefa.com/news-media/news/0209-0f8873115f5e-fb108dfaa179-1000--absteiger-holt-israelischen-pokal/' where slug='hapoel-ramat-gan' and heritage_summary is null;
update clubs set heritage_summary='עירוני טבריה ממשיכה את מסורת הכדורגל של העיר. עיריית טבריה מתארת הקמה מחדש בשם עירוני טבריה ב־2007; זה שונה משנת 2006 שמוסר הספק, ולכן שנת ההיווסדות במאגר לא שונתה ללא הצלבה נוספת.',history_source_url='https://www.tiberias.muni.il/whatsup/sport/agudotsport/' where slug='ironi-tiberias' and heritage_summary is null;
commit;
select count(*) as clubs_with_history from clubs where active and heritage_summary is not null;
